// src/utils/api.js
import axios from "axios";

const IS_LOCAL = !import.meta.env.PROD; // vite: true en dev
// si tu veux forcer la prod en local, mets BASE_PROD ci-dessous :
const BASE_PROD = "https://cdotchad.com/backend";
const BASE_ENV  = (import.meta.env.VITE_API_URL || "/backend").replace(/\/$/, "");

// En dev: utilise l'API prod (sinon proxy local). En prod: garde la valeur fournie.
const BASE = IS_LOCAL ? BASE_PROD : BASE_ENV;

const api = axios.create({
  baseURL: BASE,
  withCredentials: true,
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

api.interceptors.response.use(
  (res) => res,
  (err) => {
    const status = err?.response?.status;
    if (status === 401 || status === 403) {
      localStorage.removeItem("adminToken");
      sessionStorage.removeItem("adminToken");
    }
    return Promise.reject(err);
  }
);

export default api;
